-- Structural tables are generated by Drizzle. Policies and RPCs are maintained here.
alter table public.outings alter column updated_at set default date_trunc('milliseconds', now());
alter table public.outings add constraint owner_account foreign key (owner_id) references auth.users(id) on delete cascade;
alter table public.participants add constraint participant_account foreign key (user_id) references auth.users(id) on delete cascade;
alter table public.outings add constraint outing_times check (ends_at > starts_at and ends_at <= starts_at + interval '12 hours');
alter table public.outings add constraint outing_activity check (activity in ('drinks', 'dinner', 'coffee', 'other'));
alter table public.participants add constraint participant_name check (length(trim(name)) between 1 and 40);
alter table public.stations add constraint idf_coordinates check (latitude between 48.1 and 49.3 and longitude between 1.4 and 3.6);
create index participants_outing_idx on public.participants(outing_id);
create index outings_expiry_idx on public.outings(ends_at);

alter table public.stations enable row level security;
alter table public.outings enable row level security;
alter table public.participants enable row level security;
create policy station_catalog on public.stations for select to authenticated using (true);

create function public.is_member(target uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists(select 1 from public.participants p join public.outings o on o.id = p.outing_id where p.outing_id = target and p.user_id = auth.uid() and o.ends_at + interval '24 hours' > now());
$$;
create policy outing_members on public.outings for select to authenticated using (public.is_member(id));
create policy participant_members on public.participants for select to authenticated using (public.is_member(outing_id));
revoke all on public.outings, public.participants, public.stations from anon, authenticated;
grant select on public.outings, public.participants, public.stations to authenticated;
grant all on public.outings, public.participants, public.stations to service_role;

create function public.get_outing(outing_id uuid) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare result jsonb;
begin
  if not public.is_member($1) then raise exception 'Not a member'; end if;
  select jsonb_build_object('id', o.id, 'ownerId', o.owner_id, 'inviteCode', o.invite_code,
    'startsAt', to_char(o.starts_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'endsAt', to_char(o.ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'updatedAt', to_char(o.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'activity', o.activity, 'confirmedVenueId', o.confirmed_venue_id, 'mode', 'live',
    'participants', (select jsonb_agg(jsonb_build_object('id', p.id, 'userId', p.user_id, 'name', p.name, 'departureId', p.departure_id, 'returnId', p.return_id) order by p.joined_at, p.id) from public.participants p where p.outing_id = o.id)) into result
  from public.outings o where o.id = $1;
  return result;
end;
$$;

create function public.create_outing(payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare outing_id uuid;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  if (payload->>'startsAt')::timestamptz <= now() or (payload->>'startsAt')::timestamptz > now() + interval '7 days' then raise exception 'Date outside planning window'; end if;
  if (select count(*) from public.outings where owner_id = auth.uid()) >= 20 then raise exception 'Outing limit reached'; end if;
  insert into public.outings(owner_id, starts_at, ends_at, activity) values(auth.uid(), (payload->>'startsAt')::timestamptz, (payload->>'endsAt')::timestamptz, payload->>'activity') returning id into outing_id;
  insert into public.participants(outing_id, user_id, name, departure_id, return_id) values(outing_id, auth.uid(), trim(payload->>'name'), payload->>'departureId', payload->>'departureId');
  return public.get_outing(outing_id);
end;
$$;

create function public.join_outing(payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare outing public.outings;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  select * into outing from public.outings where invite_code = (payload->>'inviteCode')::uuid for update;
  if not found or outing.starts_at <= now() then raise exception 'Invitation expired'; end if;
  if public.is_member(outing.id) then return public.get_outing(outing.id); end if;
  if outing.confirmed_venue_id is not null then raise exception 'Outing already confirmed'; end if;
  if (select count(*) from public.participants where outing_id = outing.id) >= 10 then raise exception 'Group full'; end if;
  insert into public.participants(outing_id, user_id, name, departure_id, return_id) values(outing.id, auth.uid(), trim(payload->>'name'), payload->>'departureId', payload->>'returnId');
  update public.outings set updated_at = date_trunc('milliseconds', clock_timestamp()), recommendations = null where id = outing.id;
  return public.get_outing(outing.id);
end;
$$;

create function public.add_participant(outing_id uuid, person_name text, departure_id text, return_id text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare outing public.outings;
begin
  select * into outing from public.outings where id = $1 for update;
  if not found or outing.owner_id is distinct from auth.uid() or outing.confirmed_venue_id is not null or outing.starts_at <= now() then raise exception 'Cannot edit outing'; end if;
  if (select count(*) from public.participants p where p.outing_id = $1) >= 10 then raise exception 'Group full'; end if;
  insert into public.participants(outing_id, name, departure_id, return_id) values($1, trim($2), $3, $4);
  update public.outings set updated_at = date_trunc('milliseconds', clock_timestamp()), recommendations = null where id = $1;
  return public.get_outing($1);
end;
$$;

create function public.remove_participant(outing_id uuid, participant_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare outing public.outings;
begin
  select * into outing from public.outings where id = $1 for update;
  if not found or outing.owner_id is distinct from auth.uid() or outing.confirmed_venue_id is not null or outing.starts_at <= now() then raise exception 'Cannot edit outing'; end if;
  delete from public.participants p where p.outing_id = $1 and p.id = $2 and (p.user_id is null or p.user_id <> outing.owner_id);
  update public.outings set updated_at = date_trunc('milliseconds', clock_timestamp()), recommendations = null where id = $1;
  return public.get_outing($1);
end;
$$;

create function public.get_recommendations(outing_id uuid) returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_member($1) then raise exception 'Not a member'; end if;
  return (select recommendations from public.outings where id = $1);
end;
$$;

create function public.confirm_venue(outing_id uuid, venue_id text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare outing public.outings;
begin
  select * into outing from public.outings where id = $1 for update;
  if not found or outing.owner_id is distinct from auth.uid() or outing.starts_at <= now() then raise exception 'Cannot confirm outing'; end if;
  if outing.confirmed_venue_id is not null then raise exception 'Already confirmed'; end if;
  if outing.recommendations is null or (outing.recommendations->>'computedAt')::timestamptz < now() - interval '15 minutes' then raise exception 'Refresh recommendations'; end if;
  if not exists(select 1 from jsonb_array_elements(outing.recommendations->'recommendations') r where r->'venue'->>'id' = $2) then raise exception 'Unknown venue'; end if;
  update public.outings set confirmed_venue_id = $2, updated_at = date_trunc('milliseconds', clock_timestamp()) where id = $1;
  return public.get_outing($1);
end;
$$;

revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.is_member(uuid), public.get_outing(uuid), public.create_outing(jsonb), public.join_outing(jsonb), public.add_participant(uuid,text,text,text), public.remove_participant(uuid,uuid), public.get_recommendations(uuid), public.confirm_venue(uuid,text) to authenticated;

create extension if not exists pg_cron with schema pg_catalog;
select cron.schedule('expire-outings', '*/5 * * * *', $$delete from public.outings where ends_at + interval '24 hours' <= now()$$);
